    '[' || U&'!0001-!0008!000E-!001F!007F-!0084!0086-!009F!00AD!034F!0600-!0605!061C!0640!06DD!070F!0890-!0891!08E2!115F-!1160!17B4-!17B5!180B-!180F!200B-!200F!202A-!202E!2060-!206F!2800!3164!FE00-!FE0F!FEFF!FFA0!FFF0-!FFFB!+0110BD!+0110CD!+013430-!+01343F!+01BCA0-!+01BCA3!+01D159!+01D173-!+01D17A!+0E0000-!+0E0FFF' uescape '!' || ']', '', 'g'),
    '[' || U&'!0009-!000D!0020!0085!00A0!1680!2000-!200A!2028-!2029!202F!205F!3000' uescape '!' || ']+', ' ', 'g'), ' ')
$$;
