-- the sentence the database and the app say for a reason (the app translates it)
create or replace function public.person_name_message(n text, p text)
returns text language sql immutable parallel safe as $$
  select case p
    when 'empty' then 'Name is required'
    when 'long' then 'A name can be up to 120 characters'
    when 'digit' then 'A name cannot contain numbers'
    when 'word' then 'Each word of a name needs a letter'
    when 'mark' then 'An accent or vowel mark must sit on a letter (at most 3 on one letter)'
    when 'script' then 'Write each word of a name in one alphabet (Latin or Arabic; Greek or Cyrillic only for the whole name)'
    when 'char' then (select format('A name can only have letters, spaces and . - '' ’ ( ) , — remove “%s” (U+%s)', c, upper(lpad(to_hex(ascii(c)), greatest(4, length(to_hex(ascii(c)))), '0')))
                        from substring(n from ('[^' || U&'!0020!0027-!0029!002C-!002E!0041-!005A!0061-!007A!00C0-!00D6!00D8-!00F6!00F8-!0131!0134-!013E!0141-!0148!014A-!017E!018F!01A0-!01A1!01AF-!01B0!01CD-!01DC!01DE-!01E3!01E6-!01F0!01F4-!01F5!01F8-!021B!021E-!021F!0226-!0233!0259!0300-!0304!0306-!030C!030F-!0311!0313-!0314!031B!0323-!0328!032D-!032E!0330-!0331!0335!0338-!0339!0342!0345!037B-!037D!0386!0388-!038A!038C!038E-!03A1!03A3-!03CE!03FC-!045F!048A-!04FF!0510-!0529!052E-!052F!0620-!063F!0641-!0655!0670-!0672!0674!0679-!068D!068F-!06A0!06A2-!06D3!06D5!06E5-!06E6!06EE-!06EF!06FA-!06FC!06FF!0750-!077F!0870-!0887!0889-!088E!08A0-!08AC!08B2!08B5-!08C9!1E00-!1E99!1E9E!1EA0-!1EF9!1F00-!1F15!1F18-!1F1D!1F20-!1F45!1F48-!1F4D!1F50-!1F57!1F59!1F5B!1F5D!1F5F-!1F70!1F72!1F74!1F76!1F78!1F7A!1F7C!1F80-!1FB4!1FB6-!1FBA!1FBC!1FC2-!1FC4!1FC6-!1FC8!1FCA!1FCC!1FD0-!1FD2!1FD6-!1FDA!1FE0-!1FE2!1FE4-!1FEA!1FEC!1FF2-!1FF4!1FF6-!1FF8!1FFA!1FFC!2019!A67F!A78D!A792-!A793!A7AA!A7C0-!A7CA!A7D0-!A7D1!A7D3!A7D5-!A7D9!AB66-!AB67!+01DF00-!+01DF1E!+01DF25-!+01DF2A!+01E08F' uescape '!' || ']')) c)
  end
$$;
-- the skeleton: TR39 confusable prototypes, lower case and no Arabic short vowels, per character of the NFD name
create table if not exists private.name_skeleton (ch text primary key, sk text not null);
delete from private.name_skeleton;
insert into private.name_skeleton (ch, sk)
select chr(('x' || lpad(split_part(e, '=', 1), 8, '0'))::bit(32)::int),
       coalesce((select string_agg(chr(('x' || lpad(h, 8, '0'))::bit(32)::int), '' order by o)
