create or replace function public.person_name_key(s text)
returns text language sql stable parallel safe set search_path = '' as $$
  select normalize(array_to_string(array(
    select coalesce((select m.sk from private.name_skeleton m where m.ch = c.ch), c.ch)
      from unnest(regexp_split_to_array(normalize(public.person_name_norm(s), NFD), '')) with ordinality c(ch, i) order by c.i), ''), NFD)
$$;
-- <<< generated

revoke all on function public.person_name_norm(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_norm(text) to authenticated, service_role;          -- the name trigger runs as the writer
revoke all on function public.person_name_problem(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_problem(text) to authenticated, service_role;
revoke all on function public.person_name_message(text, text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_message(text, text) to authenticated, service_role;
revoke all on function public.person_name_key(text) from public, anon, authenticated, service_role;
grant execute on function public.person_name_key(text) to authenticated, service_role;
revoke all on table private.name_skeleton from public, anon, authenticated, service_role;
grant select on table private.name_skeleton to authenticated, service_role;                      -- read by person_name_key as the writer

-- every write of a name: normalised, checked, keyed. A browser write that breaks the rule is refused; a server write is kept and
-- flagged. A write that does not change the name keeps its key and flag (never set from outside).
create or replace function public.profiles_clean_name() returns trigger language plpgsql set search_path = public as $$
declare n text; p text;
begin
  if tg_op = 'UPDATE' and new.name is not distinct from old.name and old.name_key is not null then
    new.name_key := old.name_key; new.name_needs_fix := old.name_needs_fix; return new;
  end if;
  n := coalesce(nullif(public.person_name_norm(new.name), ''), 'Member');
  p := public.person_name_problem(n);
  if p <> '' and not public.is_server_call() then
    raise exception '%', public.person_name_message(n, p) using errcode = '23514', hint = 'name:' || p;
  end if;
  new.name := left(n, 200); new.name_needs_fix := p <> ''; new.name_key := public.person_name_key(new.name);
  return new;
end $$;
revoke all on function public.profiles_clean_name() from public, anon, authenticated, service_role;
drop trigger if exists trg_profiles_clean_name on public.profiles;
create trigger trg_profiles_clean_name before insert or update on public.profiles
  for each row execute function public.profiles_clean_name();

-- sign-up: the name typed must follow the rule (for every caller: the sign-up API runs as the server); no name → the part of the
-- e-mail before "@" in Latin letters, else "Member"
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
declare m jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb); n text := public.person_name_norm(m->>'name'); p text;
begin
  if n <> '' then
    p := public.person_name_problem(n);
    if p <> '' then raise exception '%', public.person_name_message(n, p) using errcode = '23514', hint = 'name:' || p; end if;
  else
    n := public.person_name_norm(regexp_replace(split_part(coalesce(new.email, ''), '@', 1), '[^A-Za-z]+', ' ', 'g'));
    if n = '' or public.person_name_problem(n) <> '' then n := 'Member'; end if;
  end if;
  insert into public.profiles (id, name, company, headline)
  values (new.id, n, left(nullif(trim(m->>'company'), ''), 200), left(nullif(trim(m->>'specialty'), ''), 300));
  return new;
end;
$$;
revoke all on function public.handle_new_user() from public, anon, authenticated, service_role;
grant execute on function public.handle_new_user() to authenticated, service_role;

-- ── 3. existing names (the trigger keys and flags each row) ──────────
update public.profiles set name = coalesce(nullif(public.person_name_norm(replace(name, U&'\FFFC', '')), ''), 'Member')
 where name_key is null or name is distinct from coalesce(nullif(public.person_name_norm(replace(name, U&'\FFFC', '')), ''), 'Member');
create index if not exists idx_profiles_name_key on public.profiles (name_key);
-- members read the key and the flag (0036 names every readable column: phone stays private)
grant select (name_key, name_needs_fix) on table public.profiles to anon, authenticated;

-- ── 4. conversations and candidates carry the new columns ────────────
drop function if exists public.my_conversations(int);
create function public.my_conversations(p_limit int default 30)
returns table (partner uuid, name text, headline text, verified boolean, avatar_url text,
               last_body text, last_at timestamptz, last_from_me boolean, unread int, company text, location text, name_needs_fix boolean)
language sql stable security invoker set search_path = public as $$
  select h.partner, p.name, p.headline, p.verified, p.avatar_url, h.last_body, h.last_at, h.last_from_me, h.unread, p.company, p.location, p.name_needs_fix
  from public.conversation_heads h join public.profiles p on p.id = h.partner
  where h.owner = (select auth.uid())
  order by h.last_at desc
  limit least(greatest(coalesce(p_limit, 30), 1), 100)
$$;
revoke all on function public.my_conversations(int) from public, anon, authenticated, service_role;
grant execute on function public.my_conversations(int) to authenticated, service_role;

create or replace function public.open_candidates(p_limit int default 40)
returns setof public.profiles language sql stable set search_path = public as $$
  select p.id, p.name, p.headline, p.company, p.country, p.bio, p.avatar_url, p.cover_url, p.website, null::text, p.certs, p.role,
         p.verified, p.account_type, p.created_at, p.updated_at, p.location, p.experience, p.education, p.certifications, p.skills,
         p.languages, p.open_to_work, p.hiring, p.profile_views, p.followers_count, p.years_experience, p.desired_role,
         p.desired_type, p.remote_ok, p.available_since, p.intro_video, p.intents, p.name_key, p.name_needs_fix
    from public.profiles p where p.open_to_work and p.id <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid)
     and p.id <> all (coalesce((select private.blocked_parties()), '{}'::uuid[]))
   order by p.created_at desc limit least(greatest(coalesce(p_limit, 40), 1), 100)
$$;
revoke all on function public.open_candidates(int) from public, anon, authenticated, service_role;
grant execute on function public.open_candidates(int) to authenticated, service_role;

notify pgrst, 'reload schema';
